def transform(grid):
    h=len(grid); w=len(grid[0]); out=[[7]*w for _ in range(h)]
    for r,row in enumerate(grid):
        if 0 in row:
            for c,v in enumerate(row):
                if v!=7: out[r][w-1-c]=v
        else:
            for c,v in enumerate(row):
                if v!=7: out[r][c]=v
    return out
